from pathlib import Path
import json,sys
expected=['S1_8K_OK','TEST=C005_P04','AP_READY=1','BAD_BSP_READ=1','BAD_AP_READ=1','BAD_INTENTS=02','BAD_FINAL=01','GOOD_INTENTS=02','GOOD_FINAL=02','AP_DONE=1','DONE']
trace=Path(sys.argv[1]).read_text(encoding='ascii',errors='replace').splitlines();checks={'trace_exact':trace==expected,'two_cpu_participation':all(x in trace for x in ['AP_READY=1','AP_DONE=1']),'bad_split_rmw_loses_update':all(x in trace for x in ['BAD_BSP_READ=1','BAD_AP_READ=1','BAD_INTENTS=02','BAD_FINAL=01']),'atomic_update_preserves_both':all(x in trace for x in ['GOOD_INTENTS=02','GOOD_FINAL=02'])};out={'format':'C005_P04_EVALUATION_V1','passed':all(checks.values()),'checks':checks,'trace':trace};Path(sys.argv[2]).write_text(json.dumps(out,indent=2)+'\n',encoding='utf-8',newline='\n');print(json.dumps(out,indent=2));raise SystemExit(0 if out['passed'] else 1)
